import{_ as r,o,c as t,a5 as a}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"第六步：最容易混淆的几个点","description":"no cache 不等于 no store no cache 是“能存，但每次复用前必须验证”；no store 才是“别存”。这两个混了，排查会一直错方向。(MDN Web Docs) ETag / Last Modified 不是“缓存多久”的头 它们只负责 验证 ，不负责。","frontmatter":{"title":"第六步：最容易混淆的几个点","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","前端知识复习"],"description":"no cache 不等于 no store no cache 是“能存，但每次复用前必须验证”；no store 才是“别存”。这两个混了，排查会一直错方向。(MDN Web Docs) ETag / Last Modified 不是“缓存多久”的头 它们只负责 验证 ，不负责。","sidebarWeight":36,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/考点难点/浏览器的缓存机制/第六步：最容易混淆的几个点.md"},"headers":[],"relativePath":"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/第六步：最容易混淆的几个点.md","filePath":"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/第六步：最容易混淆的几个点.md"}'),s={name:"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/第六步：最容易混淆的几个点.md"};function n(c,e,l,d,i,p){return o(),t("div",null,[...e[0]||(e[0]=[a('<div><h1 id="第六步-最容易混淆的几个点" tabindex="-1">第六步：最容易混淆的几个点 <a class="header-anchor" href="#第六步-最容易混淆的几个点" aria-label="Permalink to &quot;第六步：最容易混淆的几个点&quot;">​</a></h1><blockquote><p>本节目标：理解“第六步：最容易混淆的几个点”的核心思路，并能把它用于实际开发或面试表达。 <strong>no-cache 不等于 no-store</strong> no-cache 是“能存，但每次复用前必须验证”；no-store 才是“别存”。这两个混了，排查会一直错方向。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p></blockquote><p><strong>ETag / Last-Modified 不是“缓存多久”的头</strong> 它们只负责<strong>验证</strong>，不负责 freshness。真正决定“多久内可直接用”的还是 Cache-Control / Expires / 启发式缓存。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Vary 不是“提示”，而是缓存 key 的一部分</strong> 只要你的响应会因为某个请求头不同而不同，就必须把它写进 Vary。否则缓存很容易串。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Vary?utm_source=chatgpt.com" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Expires 不是现代主角</strong> 只要有 Cache-Control: max-age，浏览器就应忽略 Expires。Expires 现在更像补充或兼容。(<a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">RFC Editor</a>)</p><p><strong>public / s-maxage 主要是给共享缓存看的</strong> 看浏览器本地缓存时，不要把它们当主角；看 CDN / 代理缓存时，它们就很关键。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p></div>',1)])])}const f=r(s,[["render",n]]);export{g as __pageData,f as default};
